def backfill_history(apps, schema_editor):
    """Requests from before this workflow get the events they would have
    written -- "submitted" when created, then the review outcome -- so the
    history page reads continuously across the change."""
    Request = apps.get_model("data_quality_center", "SectionEditRequest")
    Event = apps.get_model("data_quality_center", "ReviewEvent")
    Edit = apps.get_model("data_quality_center", "SectionEdit")
    outcome = {"approved": "approved", "rejected": "rejected"}
    for req in Request.objects.all().iterator():
        Request.objects.filter(pk=req.pk).update(
            submitted_at=req.created_at, updated_at=req.reviewed_at or req.created_at
        )
        submitted = Event.objects.create(
            request_id=req.pk, actor_id=req.requested_by_id, actor_username=req.requested_by_username,
            action="submitted", note=req.reason,
        )
        Event.objects.filter(pk=submitted.pk).update(created_at=req.created_at)
        if req.status in outcome and req.reviewed_at:
            reviewed = Event.objects.create(
                request_id=req.pk, actor_id=req.reviewed_by_id, actor_username=req.reviewed_by_username,
                action=outcome[req.status], note=req.review_note,
            )
            Event.objects.filter(pk=reviewed.pk).update(created_at=req.reviewed_at)
        if req.status == "approved":
            # the ledger row this approval wrote: same section and text
            Edit.objects.filter(
                request__isnull=True, section_id=req.section_id,
                after_fa=req.after_fa, after_en=req.after_en,
            ).update(request_id=req.pk)


